var BaseReward = EvalFormula({Commission_Bounty_NodeCurrency});
var RankModifier = 1.0;

if (GetNodeToPlayerReputationRank() == ENodeReputationRank::Noble) {
   set RankModifier = 1.5;
} else {
   if (GetNodeToPlayerReputationRank() == ENodeReputationRank::Aristocrat) {
      set RankModifier = 1.5;
   }
}
 

return BaseReward * RankModifier;

